      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "Support the refreshment settings and control",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["table", "desk", "stand"],
        "required_properties": ["flat top", "stable"]
