        "required": true
      },
      {
        "id": "on_surface_control",
        "relation": "on",
        "participant_roles": ["entertainment_control", "surface"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "provide_refreshment_settings",
        "operation": "place",
        "participant_roles": ["refreshment_setting", "surface"],
        "operation_count": 2
      },
      {
        "id": "position_entertainment_control",
        "operation": "place",
        "participant_roles": ["entertainment_control", "surface"],
